output.text:
{"connection_id": "BC-87d7db99a2ebc49f08a4", "ref": "Augustine, Tractates on the Gospel of John 67.2", "target": "sec13", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "many dwellings in the Father's house", "note": "Augustine reads John 14's many dwellings as the differing places of blessedness in God's one house, making the destination more than a passing lodging."}
{"connection_id": "BC-66cf2ce9c4e0865ad991", "ref": "Didache 14:1", "target": "sec13", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "gathered assembly and pure sacrifice", "note": "The Didache directs the community to gather, give thanks, and make its sacrifice pure; it is an early Christian liturgical continuation of gathered worship and offering."}
{"connection_id": "BC-7a68b4febdae4d57f47f", "ref": "Justin Martyr, Dialogue with Trypho 117", "target": "sec13", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Malachi's offering read eucharistically", "note": "Justin identifies Malachi's pure offering with Christian Eucharistic bread and cup, changing the prophetic name-and-offering text into a communal Christian rite."}
{"connection_id": "BC-2d6f9495d28fee471311", "ref": "SBLGNT:1Cor.5.7", "target": "sec13", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Christ interpreted as the Passover lamb", "note": "The commentary describes an animal brought for sacrifice; Paul identifies Christ as the Passover lamb sacrificed and uses that reading to frame the community's feast."}
{"connection_id": "BC-62831912d940ee21ddbc", "ref": "SBLGNT:1Cor.5.7", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "Christ as Passover sacrifice", "note": "Paul calls Christ the sacrificed Passover; read beside Exodus 12, it recasts the household-protecting sacrificial pattern through Christ rather than a Temple-bound animal."}
{"connection_id": "BC-2c75b67df87f1a75a600", "ref": "SBLGNT:1Pet.2.5", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "the community as a spiritual house", "note": "The commentary describes livestock brought to a House for worship; Peter calls believers living stones in a spiritual house who offer spiritual sacrifices, interpreting sanctuary and offering through a community."}
{"connection_id": "BC-be7a385d7eb3a8819d92", "ref": "SBLGNT:1Pet.2.5", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "spiritual house and sacrifices", "note": "Believers are built into a spiritual house and holy priesthood to offer spiritual sacrifices, fusing house, communal belonging, and worship."}
{"connection_id": "BC-7768aeef6ef88a5df4cb", "ref": "SBLGNT:2Cor.11.2", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "betrothed and presented to one husband", "note": "Paul says he betrothed the community to one husband in order to present it as a pure virgin to Christ, directly recasting bride-transfer in ecclesial terms."}
{"connection_id": "BC-9b67397ca861f2be25d0", "ref": "SBLGNT:3John.1.5", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "hospitality to strangers", "note": "The author praises faithful service to brothers who are strangers, a concrete Christian mandate to receive travelling outsiders."}
{"connection_id": "BC-f76d8390c5c6ea9c77a9", "ref": "SBLGNT:3John.1.7", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "travel undertaken for the Name", "note": "The travelling brothers go out for the sake of the Name while taking nothing from outsiders, relating hospitality to named religious mission."}
{"connection_id": "BC-e145f1f9bce9e51e3b08", "ref": "SBLGNT:Acts.10.4", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "alms remembered before God", "note": "The commentary links an offering with nearness to God and a gift with care for another; the angel tells Cornelius that his prayers and alms have risen as a memorial before God."}
{"connection_id": "BC-e5b639e82a77af172fc7", "ref": "SBLGNT:Acts.11.29", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "relief gift for a distant community", "note": "The disciples determine to send relief to the brothers living in Judea, an actual communal gift conveyed to people in need."}
{"connection_id": "BC-af47e92f773205602bf4", "ref": "SBLGNT:Acts.11.30", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "relief sent by named carriers", "note": "The relief is sent to the elders through Barnabas and Saul, preserving the physical mediation of a gift's journey to its recipients."}
{"connection_id": "BC-8705851da414158914df", "ref": "SBLGNT:Acts.16.34", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "prisoners welcomed into the jailer's house", "note": "The jailer brings Paul and Silas into his house and sets food before them after their release, converting a scene of custody and fear into domestic welcome."}
{"connection_id": "BC-426eae049a2b6e186e1f", "ref": "SBLGNT:Acts.24.17", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "alms and offerings brought after travel", "note": "Paul says that after years away he came to bring alms for his nation and offerings, directly joining travel, gift, and cultic act."}
{"connection_id": "BC-38298984dfe49438c6ce", "ref": "SBLGNT:Acts.28.2", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "shipwrecked strangers shown kindness", "note": "After shipwreck, the islanders show unusual kindness and kindle a fire for all the survivors, a narrative of emergency welcome."}
{"connection_id": "BC-d58b719b39b70fd08dbb", "ref": "SBLGNT:Acts.28.7", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "shipwrecked travelers received into a house", "note": "Publius receives Paul and the shipwrecked party and entertains them for three days, an explicit house-based shelter for travellers."}
{"connection_id": "BC-867c6cb2aeb842698c79", "ref": "SBLGNT:Acts.8.31", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "a traveler asks for a guide", "note": "The commentary's ihdinā is a request for guidance; the Ethiopian traveler asks how he can understand Isaiah unless someone guides him, and Philip joins him on the road."}
{"connection_id": "BC-fdaae59e0f6e16ea0482", "ref": "SBLGNT:Acts.8.32", "target": "sec13", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "the sheep led to slaughter", "note": "The commentary's hedy is an animal led to a sacred destination; Acts quotes Isaiah's sheep led to slaughter in Philip's explanation of Jesus, making the sacrificial animal a Christian reading of a human figure."}
{"connection_id": "BC-a8f9cdd2198e6b24495e", "ref": "SBLGNT:Eph.2.12", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "strangers to covenants", "note": "Ephesians names Gentiles as aliens from Israel and strangers to the covenants; it gives the exclusion from which the commentary's asylum-and-covenant image moves."}
{"connection_id": "BC-7bdee63b5f79fb331879", "ref": "SBLGNT:Eph.2.19", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "strangers become God's household", "note": "Those once strangers and aliens become fellow citizens and members of God's household, an unusually direct Christian counterpart to secure communal belonging."}
{"connection_id": "BC-6364961f26aa4b093751", "ref": "SBLGNT:Eph.5.2", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "loving self-gift as sacrifice", "note": "The commentary defines a gift as kindness sent to someone loved and the hedy as an offering for nearness to God; Ephesians says Christ loved people and gave himself as an offering and sacrifice to God."}
{"connection_id": "BC-fc14da971878b3c65a7b", "ref": "SBLGNT:Eph.5.27", "target": "sec13", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "the bride presented to the husband", "note": "The commentary says the bride is gathered to her husband; Ephesians reads marriage as Christ presenting the church to himself, a Christian interpretation that turns the household image into Christ and church."}
{"connection_id": "BC-211f48a27983f7c1d708", "ref": "SBLGNT:Eph.5.27", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "bride presented to Christ", "note": "Christ presents the church to himself in splendor; the marital image supplies the end-point of a bride brought to her husband."}
{"connection_id": "BC-a0dc7972a7de9c3475cb", "ref": "SBLGNT:Heb.10.19", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "entry into holy place through sacrifice", "note": "Believers have confidence to enter the holy places by Jesus' blood; sacrifice here grants access to the sacred destination."}
{"connection_id": "BC-e67365f77ccc4a1187d5", "ref": "SBLGNT:Heb.10.20", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "new and living way", "note": "The access of the preceding verse is described as a new and living way, explicitly making sacrificial approach a path."}
{"connection_id": "BC-eddde4badbaa950892d0", "ref": "SBLGNT:Heb.11.16", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "a homeland prepared by God", "note": "The commentary says guidance has a home at the end of its road; Hebrews describes travelers seeking a better homeland and a city God has prepared for them."}
{"connection_id": "BC-83ac697e3a631c1102ca", "ref": "SBLGNT:Heb.11.16", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "country desired and city prepared", "note": "The faithful seek a better, heavenly country, and God has prepared a city for them; pilgrimage toward a divinely prepared home is explicit."}
{"connection_id": "BC-8faf2dedeaa2ae3871f8", "ref": "SBLGNT:Heb.12.22", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "arrival at heavenly Zion", "note": "Believers have come to Mount Zion and the city of the living God, expressing the destination as an already approached heavenly sanctuary."}
{"connection_id": "BC-ffbc2277ac5d487f73d3", "ref": "SBLGNT:Heb.13.11", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "animals' blood enters the sanctuary", "note": "The commentary's hedy is brought to the House as an offering; Hebrews describes sacrificial animals whose blood the high priest brings into the holy place while their bodies are burned outside camp."}
{"connection_id": "BC-f47208e19fcb57932ec3", "ref": "SBLGNT:Heb.13.12", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "sacrifice outside the city", "note": "The commentary's animal reaches the sacred House; Hebrews says Jesus suffered outside the city gate and sanctified people by his blood, relocating the Christian sacrifice beyond the city."}
{"connection_id": "BC-5ee0206c51cfbbde8263", "ref": "SBLGNT:Heb.13.14", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "seeking the city to come", "note": "Christians have no lasting city here but seek the city that is coming, a compact formulation of road-like yearning for final belonging."}
{"connection_id": "BC-c0c2f2d68d1621d8d2c0", "ref": "SBLGNT:Heb.13.15", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "praise offered with God's name", "note": "The commentary joins sacrifice, worship, and the name spoken over the animal; Hebrews calls praise a sacrifice to God and the fruit of lips that acknowledge his name."}
{"connection_id": "BC-5912c00616294017e6e1", "ref": "SBLGNT:Heb.13.15", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "sacrifice of praise and confession of Name", "note": "Through Jesus believers offer continual praise to God, identified as lips confessing his name; name and sacrifice are made verbal rather than animal."}
{"connection_id": "BC-ddba1c504e4e1af48efb", "ref": "SBLGNT:Heb.13.16", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "sharing as a pleasing sacrifice", "note": "The commentary calls a gift an act of kindness to someone loved; Hebrews says doing good and sharing resources are sacrifices pleasing to God."}

{"connection_id": "BC-010b920848dee4ba2d63", "ref": "SBLGNT:Heb.6.18", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "refuge under an oath", "note": "The commentary's asylum seeker asks a group for shelter or a pledge; Hebrews describes people who fled for refuge to seize hope grounded in God's unchangeable promise and oath."}
{"connection_id": "BC-4ac3c2ac9331bb1442ae", "ref": "SBLGNT:Heb.6.18", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "fleeing for refuge", "note": "The author speaks of people who have fled for refuge to hold fast hope; an asylum image is used directly, even though its meaning is theological."}
{"connection_id": "BC-16bfbacd619726f273bc", "ref": "SBLGNT:Heb.6.19", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "hope enters the inner sanctuary", "note": "Hope enters the inner place behind the curtain, carrying the refuge image into access to God's sanctuary rather than a secular shelter."}
{"connection_id": "BC-db8140fdc6f483867d7c", "ref": "SBLGNT:Heb.9.15", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "sacrifice mediates covenantal inheritance", "note": "Christ's death mediates a new covenant so those called may receive the promised eternal inheritance, relating sacrifice to secure belonging rather than an animal's arrival."}
{"connection_id": "BC-8d88480282c0444701cf", "ref": "SBLGNT:John.10.3", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "sheep called by name and led", "note": "The commentary says God's name is uttered over the hedy and the animal is taken toward its destination; Jesus' shepherd calls his own sheep by name and leads them out, though here the sheep are living followers."}
{"connection_id": "BC-76618fe9b8d504200c66", "ref": "SBLGNT:John.10.3", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "shepherd calls by name and leads sheep", "note": "The shepherd calls his own sheep by name and leads them out; animal, name, and guidance are joined, though the sheep are not sacrificial offerings."}
{"connection_id": "BC-bfa4dd4e53950423ec04", "ref": "SBLGNT:John.10.9", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "door, safety, and pasture", "note": "Whoever enters through Jesus is saved and finds pasture; the doorway turns guidance into safety and sustenance rather than a Temple destination."}
{"connection_id": "BC-4893d5ac87911653bafc", "ref": "SBLGNT:John.12.3", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "a costly gift offered to a beloved guest", "note": "The commentary defines a gift as kindness sent to someone cherished; Mary pours costly perfume on Jesus at a meal, and he defends her act as appropriate to his burial."}
{"connection_id": "BC-d39e15fa8ad104feaaca", "ref": "SBLGNT:John.12.3", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "costly gift in a house", "note": "Mary pours costly perfume on Jesus in a house, a concrete gift of devotion whose domestic setting and beloved recipient recall the commentary's gift image."}
{"connection_id": "BC-e8161c8b6669a6e24ad0", "ref": "SBLGNT:John.14.2", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "home prepared for the travelers", "note": "The commentary says the guided path has a house at its end; Jesus promises his disciples many dwelling places in his Father's house."}
{"connection_id": "BC-29c8b241b063ea0c5452", "ref": "SBLGNT:John.14.2", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "Father's house with prepared rooms", "note": "Jesus describes his Father's house as having many dwelling places, giving the prayer for guidance an explicitly eschatological house as destination."}
{"connection_id": "BC-afc2f984cf01738674a2", "ref": "SBLGNT:John.14.3", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "the guide takes people to himself", "note": "The commentary's bride reaches her husband's home and the refugee his safe place; Jesus promises to come and take his followers to himself so they can be where he is."}
{"connection_id": "BC-65b01e4921d5633ab34a", "ref": "SBLGNT:John.14.3", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "taking followers to himself", "note": "Jesus promises to come again and take his followers to himself so that they may be where he is, turning destination into belonging with a person."}
{"connection_id": "BC-0da30a2233add90790ae", "ref": "SBLGNT:John.14.6", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "the way to the Father", "note": "Jesus calls himself the way to the Father; the Christian text personalizes the path whose end is the Father's house in the same discourse."}
{"connection_id": "BC-87ebc6a1e8c1149d9189", "ref": "SBLGNT:John.17.12", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "kept in the Father's Name", "note": "Jesus says he guarded his followers in the Father's name and none was lost except the designated exception; the name is presented as protective custody."}
{"connection_id": "BC-73ae5f77270fbdcd7125", "ref": "SBLGNT:John.19.36", "target": "sec13", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "the Passover rule read through Jesus", "note": "The commentary's hedy is an animal designated for sacrifice; John interprets Jesus' unbroken bones through the Passover lamb rule, extending the animal offering image to his death."}
{"connection_id": "BC-4414ef48df77a41f20ff", "ref": "SBLGNT:John.20.16", "target": "sec13", "tradition": "incil", "kind": "soydas", "basis": "Aramaic Rabbouni as teacher", "note": "The commentary labels Arabic rabb as Lord and reports a covenant-related branch; Mary calls the risen Jesus Rabbouni, an Aramaic honorific meaning teacher or master, supporting the address sense rather than covenant."}
{"connection_id": "BC-d1a2bcb30df714281333", "ref": "SBLGNT:John.3.29", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "bride, bridegroom, and rejoicing friend", "note": "John calls the bride the bridegroom's and identifies the listening friend who rejoices at his voice; bride, husband, and friend are explicitly differentiated."}
{"connection_id": "BC-61bf2f3bda4b3d129f9d", "ref": "SBLGNT:John.4.21", "target": "sec13", "tradition": "incil", "kind": "karsi_anlati", "basis": "worship no longer tied to either mountain", "note": "The commentary follows the hedy to the Haram and the old House; Jesus tells the Samaritan woman that the hour comes when worship will be neither on her mountain nor in Jerusalem."}
{"connection_id": "BC-4fcc75f44581986bda98", "ref": "SBLGNT:John.4.23", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "worship in spirit and truth", "note": "The commentary locates the sacrificial animal's destination at a sacred House; Jesus describes the coming worship as in spirit and truth, shifting attention from a sanctuary site to the worshippers' manner."}
{"connection_id": "BC-829b63c688415ff6b68f", "ref": "SBLGNT:Luke.1.79", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "feet guided to peace", "note": "The commentary's ihdinā asks to be led on a path; Zechariah says the dawn from on high will guide people's feet into the way of peace."}
{"connection_id": "BC-2aa19cc11046f4e9415c", "ref": "SBLGNT:Luke.1.79", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "guiding feet into peace", "note": "Zacharias says God's dawn will guide feet into the way of peace, a focused New Testament articulation of the prayer for guidance without the house image."}
{"connection_id": "BC-a44a058dc2939e9044de", "ref": "SBLGNT:Luke.10.34", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "wounded traveler carried to shelter", "note": "The Samaritan puts the wounded man on his own animal, brings him to an inn, and cares for him, a notably close scene of transport into safety."}
{"connection_id": "BC-1426bbcc069a0e8ce0d5", "ref": "SBLGNT:Luke.15.5", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "lost sheep carried", "note": "The commentary's hedy animal is carried from a flock toward the House; Jesus' parable has a shepherd carry a recovered sheep on his shoulders, turning the journey into rescue rather than sacrifice."}
{"connection_id": "BC-78e69f96629a63e1a801", "ref": "SBLGNT:Luke.15.5", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "lost sheep carried on shoulders", "note": "After finding the sheep, the shepherd puts it on his shoulders rejoicing; this is the carrying action that culminates in the homecoming already represented by the next verse."}
{"connection_id": "BC-cc90f48611062f4f6405", "ref": "SBLGNT:Luke.15.6", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "sheep brought home, neighbors gathered", "note": "The commentary hears ihdinā as a road that reaches home; the shepherd returns with the sheep and calls friends and neighbors together to celebrate."}
{"connection_id": "BC-13eec95c1016e959a36b", "ref": "SBLGNT:Luke.15.6", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "lost sheep brought home", "note": "The shepherd comes home with the recovered sheep and calls friends and neighbors to rejoice; return, animal, home, and friendship meet in the parable."}
{"connection_id": "BC-bf72b1f24294f6e7409f", "ref": "SBLGNT:Luke.2.22", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "a family brings a child to the sanctuary", "note": "The commentary's route ends at a sacred House; Luke has Jesus' parents bring him to Jerusalem for presentation and purification under the Law."}
{"connection_id": "BC-95cce76c78a28416bb74", "ref": "SBLGNT:Luke.2.22", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "bringing a child to Jerusalem", "note": "Mary and Joseph bring Jesus to Jerusalem to present him to the Lord, a New Testament movement of a person toward the holy place for cultic presentation."}
{"connection_id": "BC-0dd51ef00b11e322a8cb", "ref": "SBLGNT:Luke.2.24", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "two birds offered at the sanctuary", "note": "The commentary describes livestock carried to a sacred destination; Luke specifies the poor family's pair of doves or pigeons as the offering brought with Jesus to the Temple."}
{"connection_id": "BC-f89b95e09a3f680679ad", "ref": "SBLGNT:Luke.2.24", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "offering at presentation", "note": "The couple offers the prescribed birds at the Temple; this supplies the animal-offering side of the Jerusalem presentation scene."}
{"connection_id": "BC-d0dc96c315552ec5eab5", "ref": "SBLGNT:Mark.1.3", "target": "sec13", "tradition": "incil", "kind": "karsi_anlati", "basis": "the path is prepared for the Lord", "note": "The commentary's prayer asks God to guide worshippers on the straight way; Mark applies Isaiah's road formula to John preparing the Lord's way, reversing who is guided and who comes."}
{"connection_id": "BC-21136cc6beb9f90b4d4f", "ref": "SBLGNT:Matt.12.42", "target": "sec13", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Queen of the South as witness", "note": "The commentary's Queen of Sheba sends Solomon a gift that he rejects; Matthew remembers her journey from earth's ends to hear Solomon and makes her a witness against Jesus' generation, adding a judgment interpretation."}
{"connection_id": "BC-75e4ee9a45f06f14a63e", "ref": "SBLGNT:Matt.2.11", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "gift delivered to a child in a house", "note": "The commentary describes a gift carried to its recipient and contrasts the rejected gift to Solomon; the Magi enter a house, worship the child, and present him gifts that are received."}
{"connection_id": "BC-c47f33c9b445ca674d5f", "ref": "SBLGNT:Matt.2.11", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "house, worship, and gifts", "note": "The magi enter a house, worship the child, and open their treasures; destination, reverence, and a carried gift converge without requiring the gift to be a sacrifice."}

{"connection_id": "BC-13d4f33c3d9633e3424d", "ref": "SBLGNT:Matt.2.13", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "a family flees to safety", "note": "The commentary describes a petitioner seeking protection and a safe destination; Joseph takes the child and mother to Egypt to escape Herod's threat."}
{"connection_id": "BC-49d2ba00130f45ea58b8", "ref": "SBLGNT:Matt.2.13", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "fleeing with child and mother", "note": "An angel directs Joseph to take the child and mother and flee to Egypt from lethal danger, a New Testament journey of protected asylum."}
{"connection_id": "BC-67e177c004707c47cd19", "ref": "SBLGNT:Matt.2.14", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "family carried into refuge", "note": "Joseph takes the child and mother by night and withdraws to Egypt, giving the refugee movement itself its own narrative verse."}
{"connection_id": "BC-41b31b3680051e51f743", "ref": "SBLGNT:Matt.2.20", "target": "sec13", "tradition": "incil", "kind": "paralel", "basis": "guided return when danger passes", "note": "The angel tells Joseph to take the child and mother back to Israel because the threat has died; refuge ends in a guided return home."}
