{"connection_id":"BC-2a60fa862ae35363e024","ref":"WLC:Dan.2.48","status":"rejected","reason":"Aramaic rav describes Daniel's high rank, not a protective covenant or the Arabic ribaba sense.","paragraphs":[],"evidence":["WLC:Dan.2.48"],"annotations":[]}
{"connection_id":"BC-1ed946cbdfa5197d22c0","ref":"WLC:Deut.12.11","status":"accepted","reason":"Offerings are brought to chosen place where divine Name dwells, as annotation states.","paragraphs":[62],"evidence":["WLC:Deut.12.5","WLC:Deut.12.11","WLC:Deut.16.2"],"annotations":["S001-TEV-MTF-001"]}

{"connection_id":"BC-59afbcc4f5229d5d676d","ref":"WLC:Deut.23.16","status":"rejected","reason":"Verse 16 forbids surrender of fugitive slave; choosing dwelling and no oppression are in verse 17.","paragraphs":[],"evidence":["WLC:Deut.23.16"],"annotations":[]}
