text(await tools.apply_patch("*** Begin Patch
*** Update File: /Volumes/aro/projects/prose_generation/enrichment/bible/work/s001/ehlikitap-images.sol.max.session-20261005/sec13/verdicts.jsonl
@@
 {"connection_id":"BC-33a7f67cd5a5824bbd66","ref":"WLC:Josh.9.18","status":"rejected","reason":"Israel does not strike Gibeonites because leaders swore, but verse 19 states obligation explicitly and is cited in the annotation.","paragraphs":[],"evidence":["WLC:Josh.9.18"],"annotations":[]}
+{"connection_id":"BC-d758d2455c68e7eacd5c","ref":"WLC:Josh.9.19","status":"accepted","reason":"Leaders invoke their sworn oath and say they cannot harm Gibeonites, showing the covenant's protective force.","paragraphs":[63],"evidence":["WLC:Deut.23.16","WLC:Deut.23.17","WLC:Josh.20.4","WLC:Josh.9.15","WLC:Josh.9.19","WLC:Exod.21.14"],"annotations":["S001-TEV-MTF-005"]}
+{"connection_id":"BC-4f8579f3560d3e189779","ref":"WLC:Lev.1.2","status":"accepted","reason":"Hebrew qorban and Arabic qurbah belong to the q-r-b nearness family, with an offering from herd or flock explicitly named.","paragraphs":[62],"evidence":["WLC:Lev.1.2","WLC:Lev.1.3"],"annotations":["S001-TEV-SYD-001"]}
+{"connection_id":"BC-7cee96edc1bee9dd3290","ref":"WLC:Lev.1.2","status":"accepted","reason":"Leviticus explicitly prescribes an offering from herd or flock to YHWH, analogous to hedy animal.","paragraphs":[62],"evidence":["WLC:Lev.1.2","WLC:Lev.1.3"],"annotations":["S001-TEV-SYD-001"]}
+{"connection_id":"BC-f35ea5358e090b11dbd4","ref":"WLC:Lev.1.3","status":"accepted","reason":"Unblemished herd animal is brought to the Tent entrance for offering before YHWH.","paragraphs":[62],"evidence":["WLC:Lev.1.2","WLC:Lev.1.3"],"annotations":["S001-TEV-SYD-001"]}
+{"connection_id":"BC-682a07055001b799efc6","ref":"WLC:Lev.1.3","status":"accepted","reason":"Cultic animal reaches the sacred entrance and is presented before YHWH; destination differs from Qur'anic Haram.","paragraphs":[62],"evidence":["WLC:Lev.1.2","WLC:Lev.1.3"],"annotations":["S001-TEV-SYD-001"]}
+{"connection_id":"BC-e2b1f4d3d8e878948362","ref":"WLC:Lev.1.4","status":"rejected","reason":"Hand placement and atonement concern acceptance of sacrifice, but the verse has no transported animal or destination.","paragraphs":[],"evidence":["WLC:Lev.1.4"],"annotations":[]}
+{"connection_id":"BC-02a0d757cbcec80a30ab","ref":"WLC:Lev.17.4","status":"rejected","reason":"A person who fails to bring a slaughtered animal to Tent entrance incurs guilt; Lev 1:3 more directly depicts actual arrival.","paragraphs":[],"evidence":["WLC:Lev.17.4"],"annotations":[]}
+{"connection_id":"BC-76b5e0d29af3ee6f4db9","ref":"WLC:Lev.17.5","status":"rejected","reason":"Animal sacrifice at Tent entrance restates the Leviticus cultic destination already shown at Lev 1:2-3, without further narrative nuance.","paragraphs":[],"evidence":["WLC:Lev.17.5"],"annotations":[]}
+{"connection_id":"BC-17939d45aa6474fa29ab","ref":"WLC:Lev.23.2","status":"accepted","reason":"YHWH's appointed times are named holy convocations, supporting the commentary's season-and-gathering image without equating calendars.","paragraphs":[62],"evidence":["WLC:Lev.23.2","WLC:Deut.16.16"],"annotations":["S001-TEV-MTF-002"]}
+{"connection_id":"BC-6264b87c4a0c85346f7a","ref":"WLC:Lev.27.28","status":"rejected","reason":"Hebrew herem concerns irrevocable devotion to YHWH and non-sale; it does not prove the commentary's hurma of a protected person or hedy.","paragraphs":[],"evidence":["WLC:Lev.27.28"],"annotations":[]}
+{"connection_id":"BC-3d20e8e5098bf2f42e28","ref":"WLC:Mal.1.10","status":"rejected","reason":"YHWH refuses unacceptable cultic offerings, not a ruler's political gift to an enemy; the commentary's claim is narrower.","paragraphs":[],"evidence":["WLC:Mal.1.10"],"annotations":[]}
+{"connection_id":"BC-8fad15a15571c789456d","ref":"WLC:Mal.1.11","status":"rejected","reason":"Name and pure offering among nations are clear, but no herd, house or journey is given; Deut 12:11 carries the contextual point more precisely.","paragraphs":[],"evidence":["WLC:Mal.1.11"],"annotations":[]}
+{"connection_id":"BC-2b03f7c0ebe9a4b1901a","ref":"WLC:Mal.1.11","status":"rejected","reason":"Pure offering to divine Name is a broad cultic analogue but has no animal or arrival scene; Lev 1:2-3 and Deut 12:11 are more specific.","paragraphs":[],"evidence":["WLC:Mal.1.11"],"annotations":[]}
+{"connection_id":"BC-f3840de7abbe487dcd83","ref":"WLC:Mal.1.14","status":"rejected","reason":"A male flock animal is withheld or blemished while YHWH's Name is great; it never travels to the House.","paragraphs":[],"evidence":["WLC:Mal.1.14"],"annotations":[]}
+{"connection_id":"BC-302826a38fe59341e451","ref":"WLC:Mal.2.14","status":"rejected","reason":"Wife is called covenant partner, but no bridal transfer or protective community pledge is described.","paragraphs":[],"evidence":["WLC:Mal.2.14"],"annotations":[]}
+{"connection_id":"BC-302d4eceadff437223fb","ref":"WLC:Num.10.33","status":"rejected","reason":"Ark goes before Israel seeking rest, but this verse identifies no reached home or sanctuary endpoint.","paragraphs":[],"evidence":["WLC:Num.10.33"],"annotations":[]}
+{"connection_id":"BC-af0cd1d3be5db1046642","ref":"WLC:Num.2.2","status":"rejected","reason":"Standards organize camps around Tent, but they are tribal banners rather than marks of an appointed festival season.","paragraphs":[],"evidence":["WLC:Num.2.2"],"annotations":[]}
+{"connection_id":"BC-7c5f7204031806034d2d","ref":"WLC:Num.35.11","status":"rejected","reason":"Cities of refuge are appointed for accidental killers; Josh 20:4 gives the actual gate hearing, admission, and dwelling described in the commentary.","paragraphs":[],"evidence":["WLC:Num.35.11"],"annotations":[]}
+{"connection_id":"BC-0fb523cfb138c41c3a43","ref":"WLC:Num.35.11","status":"rejected","reason":"Flight to refuge city is explicit, but the received petition and place to stay appear more fully in Josh 20:4.","paragraphs":[],"evidence":["WLC:Num.35.11"],"annotations":[]}
+{"connection_id":"BC-975a6037b963a2a9dba3","ref":"WLC:Num.35.15","status":"rejected","reason":"Refuge extends to aliens and sojourners, but this is an accidental-killer statute; Deut 23:16-17 more closely concerns a newcomer seeking residence.","paragraphs":[],"evidence":["WLC:Num.35.15"],"annotations":[]}
+{"connection_id":"BC-f1c26a3a8fc1d698f764","ref":"WLC:Num.6.27","status":"rejected","reason":"Priests place divine Name on Israel for blessing, but not on an animal brought as offering; the commentary's hedy analogy would overextend it.","paragraphs":[],"evidence":["WLC:Num.6.27"],"annotations":[]}
+{"connection_id":"BC-2f668c6ee455f645fb1f","ref":"WLC:Num.6.27","status":"rejected","reason":"Name is placed on the people, not pronounced over a herd animal, so this is a different ritual action.","paragraphs":[],"evidence":["WLC:Num.6.27"],"annotations":[]}
+{"connection_id":"BC-541b66c604b9f55f5f64","ref":"WLC:Prov.18.16","status":"rejected","reason":"Gift grants access to powerful people in a proverb; it says nothing about acceptance between enemies or arrival at a sacred House.","paragraphs":[],"evidence":["WLC:Prov.18.16"],"annotations":[]}
+{"connection_id":"BC-04b2c2b4d4b2b970827c","ref":"WLC:Ps.107.7","status":"accepted","reason":"YHWH guides wilderness wanderers by a straight way to a city where they can dwell, linking route to home.","paragraphs":[64],"evidence":["WLC:Ps.107.7"],"annotations":["S001-TEV-MTF-007"]}
+{"connection_id":"BC-caeddbb06a2b42a0dd34","ref":"WLC:Ps.107.7","status":"accepted","reason":"Direct path terminates at an inhabited city, but not a sanctuary; annotation maintains this limit.","paragraphs":[64],"evidence":["WLC:Ps.107.7"],"annotations":["S001-TEV-MTF-007"]}
+{"connection_id":"BC-fe816c714fd31fb8ea19","ref":"WLC:Ps.116.17","status":"rejected","reason":"Thanksgiving sacrifice and invoking YHWH's Name coincide, but no House appears in this verse; Deut 12:11 gives name and arrival with offerings.","paragraphs":[],"evidence":["WLC:Ps.116.17"],"annotations":[]}
+{"connection_id":"BC-de56341f27e7ffd9d853","ref":"WLC:Ps.116.17","status":"rejected","reason":"The Name accompanies thanksgiving sacrifice, but this adds no destination or animal conveyance beyond the more specific cultic texts.","paragraphs":[],"evidence":["WLC:Ps.116.17"],"annotations":[]}
+{"connection_id":"BC-71cc0810ad092bab354c","ref":"WLC:Ps.116.19","status":"rejected","reason":"Verse 19 names courts of YHWH's House, while vow payment is in verse 18; candidate combines separate verses as if both in 19.","paragraphs":[],"evidence":["WLC:Ps.116.19"],"annotations":[]}
+{"connection_id":"BC-161fcd214af456230cf6","ref":"WLC:Ps.118.26","status":"rejected","reason":"A blessed person comes in YHWH's name from the House, but the verse identifies no animal, guided route or spoken name over an offering.","paragraphs":[],"evidence":["WLC:Ps.118.26"],"annotations":[]}
+{"connection_id":"BC-38010e6d1b37cc521ee5","ref":"WLC:Ps.118.27","status":"rejected","reason":"Hebrew festival-binding phrase has a disputed referent; it cannot securely establish a hedy-like animal conveyed to altar horns.","paragraphs":[],"evidence":["WLC:Ps.118.27"],"annotations":[]}
+{"connection_id":"BC-aa716f582f6c1bae0416","ref":"WLC:Ps.122.5","status":"rejected","reason":"Candidate's tribal ascent and thanksgiving to the Name are in Ps 122:4, not 122:5, which names judgment thrones.","paragraphs":[],"evidence":["WLC:Ps.122.5"],"annotations":[]}
+{"connection_id":"BC-d3df0ce71fa2182b78c2","ref":"WLC:Ps.43.3","status":"accepted","reason":"Psalm asks divine light and truth to lead and bring speaker to holy mountain and dwellings.","paragraphs":[64],"evidence":["WLC:Exod.15.13","WLC:Exod.15.17","WLC:Ps.43.3"],"annotations":["S001-TEV-MTF-006"]}
+{"connection_id":"BC-c8bca435d849c9b9ce43","ref":"WLC:Ps.43.3","status":"accepted","reason":"Prayer joins guidance with arrival at God's sacred dwelling, paralleling the commentary's developed home image.","paragraphs":[64],"evidence":["WLC:Exod.15.13","WLC:Exod.15.17","WLC:Ps.43.3"],"annotations":["S001-TEV-MTF-006"]}
+{"connection_id":"BC-81b6d91ba696c060fe20","ref":"WLC:Ps.45.15","status":"rejected","reason":"Royal bride is led toward king, but no home is stated until verse 16; Gen 24:53,61,67 traces gifts, journey and arrival together.","paragraphs":[],"evidence":["WLC:Ps.45.15"],"annotations":[]}
+{"connection_id":"BC-1b797a1d6158707bd91e","ref":"WLC:Ps.45.16","status":"rejected","reason":"Bridal party enters king's palace, but this verse alone does not identify the central bride or full route; Gen 24 is a fuller marriage journey.","paragraphs":[],"evidence":["WLC:Ps.45.16"],"annotations":[]}
*** End Patch"));

